'use strict';
/* Daily marking and editable monthly attendance matrix, using the shared attendance records. */
let attendanceActiveView='daily',attendanceSelectedDate=today(),attendanceSelectedMonth=today().slice(0,7),attendanceSearchText='',attendanceDailyDrafts=Object.create(null);
function attendanceStaff(){return db.staff.filter(s=>s.status!=='Inactive')}
function normalizeAttendanceStatus(value){return ['P','Present'].includes(value)?'Present':['H','HD','Half Day'].includes(value)?'Half Day':['A','Absent'].includes(value)?'Absent':['PL','Paid Leave'].includes(value)?'Paid Leave':['WO','Weekly Off'].includes(value)?'Weekly Off':'Unmarked'}
function attendanceFor(date,id){if(date===attendanceSelectedDate&&attendanceDailyDrafts[date]&&Object.prototype.hasOwnProperty.call(attendanceDailyDrafts[date],id))return attendanceDailyDrafts[date][id]||{};return db.attendance?.[date]?.[id]||{}}
function getDailyDraft(){if(!attendanceDailyDrafts[attendanceSelectedDate])attendanceDailyDrafts[attendanceSelectedDate]=structuredClone(db.attendance?.[attendanceSelectedDate]||{});return attendanceDailyDrafts[attendanceSelectedDate]}
function attendanceLabel(status){const normalized=normalizeAttendanceStatus(status);return normalized==='Present'?'P':normalized==='Half Day'?'H':normalized==='Absent'?'A':normalized==='Paid Leave'?'PL':normalized==='Weekly Off'?'WO':'—'}
function attendanceTotals(date,staff=attendanceStaff()){let counts={Present:0,'Half Day':0,Absent:0};for(const person of staff){const s=normalizeAttendanceStatus(attendanceFor(date,person.id).status);if(Object.prototype.hasOwnProperty.call(counts,s))counts[s]++}return counts}
function attendanceStatCard(label,value,kind,symbol){return `<div class="attendanceStat ${kind}"><span class="attendanceStatIcon">${icon(symbol)}</span><div><small>${esc(label)}</small><strong>${esc(value)}</strong></div></div>`}
function attendanceStats(items){return `<div class="attendanceStats">${items.map(x=>attendanceStatCard(...x)).join('')}</div>`}
function attendanceTable(headers,rows,cls=''){return `<div class="tablewrap ${cls}"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(v=>`<td>${v??'—'}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="empty">No staff records match this search.</td></tr>`}</tbody></table></div>`}
function attendanceTabBar(){return `<div class="attendanceTabs"><button type="button" class="attendanceTab ${attendanceActiveView==='daily'?'active':''}" data-attendance-view="daily">${icon('calendar')}Daily Attendance Marking</button><button type="button" class="attendanceTab ${attendanceActiveView==='monthly'?'active':''}" data-attendance-view="monthly">${icon('chart')}Monthly Matrix & Payroll</button></div><div class="attendanceNotice">${icon('info')}Staff added in Staff Master automatically appear here.</div>`}
function dailyAttendanceMarkup(){const staff=attendanceStaff(),draft=getDailyDraft(),counts=(()=>{let c={Present:0,'Half Day':0,Absent:0};for(let s of staff){let status=normalizeAttendanceStatus(draft[s.id]?.status);if(Object.prototype.hasOwnProperty.call(c,status))c[status]++}return c})(),dirty=JSON.stringify(draft)!==JSON.stringify(db.attendance?.[attendanceSelectedDate]||{}),filtered=staff.filter(s=>[s.id,s.name,s.mobile,s.designation,s.skills].some(v=>String(v||'').toLowerCase().includes(attendanceSearchText.toLowerCase()))),rows=filtered.map(s=>{let status=normalizeAttendanceStatus(draft[s.id]?.status);return [esc(s.id),`<div class="attendancePerson"><span class="attendanceInitial">${esc(String(s.name||'S').trim()[0]||'S')}</span><div><strong>${esc(s.name)}</strong><small>☎ ${esc(s.mobile||'—')}</small></div></div>`,esc(s.designation||'—'),s.salaryType==='Per Job'?`${esc(s.salary)}% <small>(Per Job)</small>`:`${money(s.salary)} <small>(${esc(s.salaryType||'—')})</small>`,`<div class="attendanceChoices">${[['Present','P'],['Half Day','H'],['Paid Leave','PL'],['Weekly Off','WO'],['Absent','A']].map(([v,l])=>`<button type="button" class="attendanceChoice ${status===v?'selected '+(v==='Present'?'present':v==='Half Day'?'halfday':v==='Paid Leave'?'paidleave':v==='Weekly Off'?'weeklyoff':'absent'):''}" data-attendance-status="${v}" data-attendance-staff="${esc(s.id)}" aria-label="${v} for ${esc(s.name)}">${l}<span>${v==='Half Day'?'Half Day':v}</span></button>`).join('')}</div>`,`<input type="text" class="attendanceNote" data-attendance-note="${esc(s.id)}" value="${esc(draft[s.id]?.note||'')}" placeholder="Optional note / overtime…" aria-label="Remarks for ${esc(s.name)}">`]});
return `<section class="attendanceView" id="attendanceDailyTabContent">${attendanceStats([['TOTAL STAFF',staff.length,'dark','users'],['PRESENT',counts.Present,'green','check'],['HALF DAY',counts['Half Day'],'orange','clock'],['ABSENT',counts.Absent,'red','shield']])}<div class="attendanceControlCard"><div class="attendanceDateRow"><strong>${icon('calendar')}Date:</strong><button class="btn secondary small" type="button" data-attendance-day="-1" aria-label="Previous day">‹</button><input id="attendanceDateInput" type="date" value="${esc(attendanceSelectedDate)}" aria-label="Attendance date"><button class="btn secondary small" type="button" data-attendance-day="1" aria-label="Next day">›</button><button class="btn secondary small" type="button" data-attendance-today>Today</button><span class="attendanceSaveState ${dirty?'unsaved':'saved'}">${dirty?'Not Saved Yet ⏳':'Saved ✓'}</span></div><div class="attendanceActionsRow"><strong>Quick Mark:</strong><button type="button" class="btn quickAttendance present" data-attendance-all="Present">✓ All Present</button><button type="button" class="btn quickAttendance halfday" data-attendance-all="Half Day">◷ All Half Day</button><button type="button" class="btn quickAttendance absent" data-attendance-all="Absent">× All Absent</button><button type="button" class="btn quickAttendance paidleave" data-attendance-all="Paid Leave">PL All Paid Leave</button><button type="button" class="btn quickAttendance weeklyoff" data-attendance-all="Weekly Off">WO All Weekly Off</button><input id="attendanceDailySearch" type="search" placeholder="Search staff name, ID, designation…" aria-label="Search attendance staff" value="${esc(attendanceSearchText)}"></div><div class="attendanceSaveRow"><button class="btn attendanceSave" type="button" data-attendance-save>${icon('check')}Save Attendance</button><span>${staff.length} active staff · attendance is saved by date</span></div></div>${attendanceTable(['STAFF ID','STAFF NAME & CONTACT','DESIGNATION','SALARY SCHEME','ATTENDANCE STATUS (P / H / A)','REMARKS / NOTES'],rows,'attendanceDailyTable')}</section>`}
function monthDays(month){const [year,m]=month.split('-').map(Number),n=new Date(year,m,0).getDate();return Array.from({length:n},(_,i)=>{let d=new Date(year,m-1,i+1);return {date:`${year}-${String(m).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`,day:i+1,dow:d.toLocaleDateString('en',{weekday:'short'}),weekend:[0,6].includes(d.getDay())}})}
function attendanceSalaryEstimate(staff,counts,days){const type=String(staff.salaryType||'').trim().toLowerCase(),amount=Number(staff.salary||0);if(type==='monthly'){const dailyRate=days.length?amount/days.length:0,unpaidDays=Number(counts.absent||0)+Number(counts.half||0)*.5;return {dailyRate,estimated:Math.max(0,round(amount-unpaidDays*dailyRate)),label:'Monthly salary less absent and half-day deductions; Paid Leave is fully paid'}}if(type==='daily'){return {dailyRate:amount,estimated:amount*counts.payable,label:'Daily rate × payable days; Paid Leave counts as payable'}}if(type==='per job'){const labour=db.jobs.filter(j=>j.mechanic===staff.id&&String(j.date||'').startsWith(attendanceSelectedMonth)&&['Completed','Delivered'].includes(j.status)).reduce((sum,j)=>sum+billTotals(j).labour,0);return {dailyRate:amount,estimated:round(labour*amount/100),label:'Per-job rate × completed labour'}}return {dailyRate:0,estimated:0,label:'Set salary type in Staff Master'}}
function monthAttendanceRows(){const [year,month]=attendanceSelectedMonth.split('-').map(Number),days=monthDays(attendanceSelectedMonth),staff=attendanceStaff().filter(s=>[s.id,s.name,s.mobile,s.designation,s.skills].some(v=>String(v||'').toLowerCase().includes(attendanceSearchText.toLowerCase())));let totals={present:0,half:0,absent:0,paidLeave:0,weeklyOff:0,excessLeave:0,payable:0,estimated:0};const rows=staff.map(s=>{let counts=attendanceMonthlySummary(s,days);let cells=days.map(d=>{let status=counts.statuses[d.date];let mark=status==='Unpaid Leave'?'UL':attendanceLabel(status);return `<td class="attendanceMatrixDay ${status==='Present'?'isPresent':status==='Half Day'?'isHalf':status==='Absent'?'isAbsent':status==='Paid Leave'?'isPaidLeave':status==='Weekly Off'?'isWeeklyOff':''} ${d.weekend?'weekend':''}"><button type="button" data-attendance-cell="${esc(d.date)}" data-attendance-staff="${esc(s.id)}" aria-label="${esc(s.name)} ${esc(d.date)} ${status}" title="${esc(s.name)} · ${esc(d.date)} · ${status}"><small>${d.day}</small><strong>${mark}</strong></button></td>`});let {dailyRate,estimated}=attendanceSalaryEstimate(s,counts,days);counts.estimated=estimated;for(const key of ['present','paidLeave','weeklyOff','excessLeave','half','absent','payable','estimated'])totals[key]+=counts[key];return `<tr><td class="attendanceMatrixName"><strong>${esc(s.name)}</strong><small>${esc(s.id)} · ${esc(s.designation||'—')}</small></td><td>${s.salaryType==='Per Job'?`${esc(s.salary)}% / Job`:esc(s.salaryType||'—')}</td>${cells.join('')}<td class="attendanceMatrixTotal">${counts.present}</td><td class="attendanceMatrixTotal">${counts.paidLeave}</td><td class="attendanceMatrixTotal">${counts.weeklyOff}</td><td class="attendanceMatrixTotal">${counts.excessLeave}</td><td class="attendanceMatrixTotal">${counts.half}</td><td class="attendanceMatrixTotal">${counts.absent}</td><td class="attendanceMatrixTotal">${counts.payable.toFixed(1)}</td><td class="attendanceMatrixTotal">${s.salaryType==='Per Job'?`${esc(s.salary)}% / Job`:money(dailyRate)}</td><td class="attendanceMatrixPay">${money(estimated)}</td></tr>`});
return {days,staff,rows,totals}}
function monthlyAttendanceMarkup(){const [year,month]=attendanceSelectedMonth.split('-').map(Number),data=monthAttendanceRows(),monthLabel=new Date(year,month-1,1).toLocaleDateString('en',{month:'long',year:'numeric'}),years=Array.from({length:7},(_,i)=>year-3+i),counts=data.totals;return `<section class="attendanceView" id="attendanceMonthlyTabContent">${attendanceStats([['TOTAL STAFF',data.staff.length,'dark','users'],['TOTAL PRESENT DAYS',counts.present,'green','check'],['TOTAL HALF DAYS',counts.half,'orange','clock'],['TOTAL EST. PAYROLL',money(counts.estimated),'purple','wallet']])}<div class="attendanceControlCard monthlyControls"><div class="attendanceMonthRow"><strong>${icon('calendar')}Select Period:</strong><select id="matrixMonthSelect" aria-label="Attendance month">${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${month===i+1?'selected':''}>${new Date(2026,i,1).toLocaleDateString('en',{month:'long'})}</option>`).join('')}</select><select id="matrixYearSelect" aria-label="Attendance year">${years.map(y=>`<option value="${y}" ${year===y?'selected':''}>${y}</option>`).join('')}</select><button type="button" class="btn secondary" data-attendance-current-month>Current Month</button></div><div class="attendanceLegend"><span class="present">P <b>Present (1.0)</b></span><span class="halfday">H <b>Half Day (0.5)</b></span><span class="absent">A <b>Absent (0.0)</b></span><small>Tap a day cell to cycle its status. Changes save immediately.</small></div><div class="attendanceMatrixTools"><input id="attendanceMonthlySearch" type="search" placeholder="Filter staff…" aria-label="Filter monthly attendance staff" value="${esc(attendanceSearchText)}"><button type="button" class="btn success" data-attendance-export>${icon('download')}Export Excel</button><button type="button" class="btn" data-attendance-print>${icon('print')}Print Sheet</button></div></div><div class="attendanceMatrixWrap"><table class="attendanceMatrix"><thead><tr><th class="attendanceMatrixName">MECHANIC</th><th>SALARY SCHEME</th>${data.days.map(d=>`<th class="${d.weekend?'weekend':''}" title="${d.date}">${d.day}<small>${d.dow.toUpperCase()}</small></th>`).join('')}<th>PRESENT (P)</th><th>PAID LEAVE (PL)</th><th>WEEKLY OFF (WO)</th><th>EXCESS PL (UNPAID)</th><th>HALF DAY (HD)</th><th>ABSENT (A)</th><th>PAYABLE DAYS</th><th>DAILY RATE</th><th>EST. SALARY (₹)</th></tr></thead><tbody>${data.rows.join('')||`<tr><td colspan="${data.days.length+11}" class="empty">No staff records match this search.</td></tr>`}<tr class="attendanceMatrixGrand"><td><strong>TOTALS</strong></td><td><strong>${data.staff.length} Staff</strong></td>${data.days.map((_,i)=>`<td>${i===0?'—':''}</td>`).join('')}<td>${counts.present}</td><td>${counts.paidLeave}</td><td>${counts.weeklyOff}</td><td>${counts.excessLeave}</td><td>${counts.half}</td><td>${counts.absent}</td><td>${counts.payable.toFixed(1)}</td><td>—</td><td>${money(counts.estimated)}</td></tr></tbody></table></div><p class="attendanceMatrixFoot">${esc(monthLabel)} · Salary estimate uses the Staff Master salary type: monthly salary is reduced only for Absent and Half Day, while Paid Leave is fully paid; daily salary is multiplied by payable days; per-job percentage is applied to completed/delivered job labour for this month. Attendance is shared between both views.</p></section>`}
attendancePage=function(){getDailyDraft();return attendanceTabBar()+(attendanceActiveView==='daily'?dailyAttendanceMarkup():monthlyAttendanceMarkup())};
function setAttendanceFor(staffId,status){const draft=getDailyDraft(),previous=draft[staffId]||{};draft[staffId]={...previous,status};render()}
function markAllAttendance(status){const draft=getDailyDraft();for(const person of attendanceStaff())draft[person.id]={...(draft[person.id]||{}),status};render()}
async function saveDailyAttendance(){const date=attendanceSelectedDate;const next={...(db.attendance[attendanceSelectedDate]||{})};for(const s of attendanceStaff()){const current=getDailyDraft()[s.id]||{},note=$(`[data-attendance-note="${CSS.escape(s.id)}"]`)?.value?.trim()??current.note??'',status=normalizeAttendanceStatus(current.status);if(status!=='Unmarked'||note)next[s.id]={status,note};else delete next[s.id]}if(await window.saveCloudAttendance(date,next))render()}
async function setMatrixCell(date,staffId){const original=db.attendance[date]||{},previous=original[staffId]||{},status=normalizeAttendanceStatus(previous.status),next={...original};let cycle=['Unmarked','Present','Half Day','Absent','Paid Leave','Weekly Off'];let replacement=cycle[(cycle.indexOf(status)+1)%cycle.length];if(replacement==='Unmarked'&&!previous.note)delete next[staffId];else next[staffId]={...previous,status:replacement};if(await window.saveCloudAttendance(date,next))render()}
function attendanceCsv(rows){return '\ufeff'+rows.map(row=>row.map(cell=>'"'+String(cell??'').replace(/"/g,'""')+'"').join(',')).join('\r\n')}
function exportAttendanceMatrix(){const {days,staff}=monthAttendanceRows(),rows=[['Staff ID','Staff Name','Designation','Salary Scheme',...days.map(d=>d.date),'Present Days','Paid Leave','Weekly Off','Excess PL (Unpaid)','Half Days','Absent Days','Payable Days','Estimated Salary']];for(const s of staff){const c=attendanceMonthlySummary(s,days),values=days.map(d=>c.statuses[d.date]==='Unpaid Leave'?'UL':attendanceLabel(c.statuses[d.date]));rows.push([s.id,s.name,s.designation,s.salaryType,...values,c.present,c.paidLeave,c.weeklyOff,c.excessLeave,c.half,c.absent,c.payable,attendanceSalaryEstimate(s,c,days).estimated.toFixed(2)])}download(attendanceCsv(rows),`BIKE-DOCTOR-Attendance-${attendanceSelectedMonth}.csv`,'text/csv;charset=utf-8');toast('Attendance matrix exported')}
function printAttendanceMatrix(){const {days,staff}=monthAttendanceRows(),rows=staff.map(s=>`<tr><td>${esc(s.name)}<small>${esc(s.id)}</small></td><td>${esc(s.salaryType||'—')}</td>${days.map(d=>{const st=normalizeAttendanceStatus(attendanceFor(d.date,s.id).status);return `<td class="${st==='Present'?'p':st==='Half Day'?'h':st==='Absent'?'a':st==='Paid Leave'?'pl':st==='Weekly Off'?'wo':''}">${attendanceLabel(st)}</td>`}).join('')}</tr>`).join(''),pref=db.settings.attendancePrint||{paper:'A4',orientation:'landscape'},paper=['A3','A4','A5','Letter','Legal'].includes(pref.paper)?pref.paper:'A4',orientation=pref.orientation==='portrait'?'portrait':'landscape';openModal('Monthly Attendance Sheet',`<div class="attendancePrinterPrefs"><strong>Print Preferences</strong><label>Paper size <select id="attendancePrintPaper" aria-label="Attendance print paper size">${['A3','A4','A5','Letter','Legal'].map(v=>`<option value="${v}" ${paper===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Orientation <select id="attendancePrintOrientation" aria-label="Attendance print orientation"><option value="landscape" ${orientation==='landscape'?'selected':''}>Landscape</option><option value="portrait" ${orientation==='portrait'?'selected':''}>Portrait</option></select></label><button type="button" class="btn secondary" id="saveAttendancePrintPrefs">Save Preference</button><small>Choose the printer device in your browser’s print window.</small></div><div class="attendancePrintSheet"><h2>${esc(db.settings.name)} · Monthly Attendance</h2><p>${esc(new Date(...attendanceSelectedMonth.split('-').map(Number).map((v,i)=>i===1?v-1:v)).toLocaleDateString('en',{month:'long',year:'numeric'}))}</p><div class="attendanceMatrixWrap"><table class="attendanceMatrix"><thead><tr><th>STAFF</th><th>SCHEME</th>${days.map(d=>`<th>${d.day}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div></div><div class="formactions"><button class="btn secondary" data-action="cancel">Close</button><button type="button" class="btn" id="attendancePrintConfirm">Print Sheet</button></div>`);const readPrefs=()=>({paper:$('#attendancePrintPaper').value,orientation:$('#attendancePrintOrientation').value});$('#saveAttendancePrintPrefs').onclick=()=>{const before=structuredClone(db.settings);db.settings.attendancePrint=readPrefs();if(save('Attendance print preferences saved')===false)db.settings=before};$('#attendancePrintConfirm').onclick=()=>{const before=structuredClone(db.settings);db.settings.attendancePrint=readPrefs();if(save()===false){db.settings=before;return}let style=document.createElement('style');style.id='attendancePrintPage';style.textContent=`@media print{@page{size:${db.settings.attendancePrint.paper} ${db.settings.attendancePrint.orientation};margin:8mm}}`;document.head.appendChild(style);document.body.classList.add('attendancePrintMode');const clean=()=>{document.body.classList.remove('attendancePrintMode');style.remove();window.removeEventListener('afterprint',clean)};window.addEventListener('afterprint',clean);window.print()}}
document.addEventListener('click',e=>{const view=e.target.closest('[data-attendance-view]');if(view){attendanceActiveView=view.dataset.attendanceView;render();return}const day=e.target.closest('[data-attendance-day]');if(day){let d=new Date(attendanceSelectedDate+'T12:00:00');d.setDate(d.getDate()+Number(day.dataset.attendanceDay));attendanceSelectedDate=todayFromDate(d);attendanceDailyDrafts[attendanceSelectedDate]=structuredClone(db.attendance[attendanceSelectedDate]||{});render();return}if(e.target.closest('[data-attendance-today]')){attendanceSelectedDate=today();attendanceDailyDrafts[attendanceSelectedDate]=structuredClone(db.attendance[attendanceSelectedDate]||{});render();return}const status=e.target.closest('[data-attendance-status]');if(status){setAttendanceFor(status.dataset.attendanceStaff,status.dataset.attendanceStatus);return}const all=e.target.closest('[data-attendance-all]');if(all){markAllAttendance(all.dataset.attendanceAll);return}if(e.target.closest('[data-attendance-save]')){saveDailyAttendance();return}const cell=e.target.closest('[data-attendance-cell]');if(cell){setMatrixCell(cell.dataset.attendanceCell,cell.dataset.attendanceStaff);return}if(e.target.closest('[data-attendance-current-month]')){attendanceSelectedMonth=today().slice(0,7);attendanceSearchText='';render();return}if(e.target.closest('[data-attendance-export]')){exportAttendanceMatrix();return}if(e.target.closest('[data-attendance-print]')){printAttendanceMatrix()}});
document.addEventListener('change',e=>{if(e.target.id==='attendanceDateInput'){attendanceSelectedDate=e.target.value||today();attendanceDailyDrafts[attendanceSelectedDate]=structuredClone(db.attendance[attendanceSelectedDate]||{});render()}if(e.target.id==='matrixMonthSelect'||e.target.id==='matrixYearSelect'){const month=$('#matrixMonthSelect').value,year=$('#matrixYearSelect').value;attendanceSelectedMonth=`${year}-${String(month).padStart(2,'0')}`;attendanceSearchText='';render()}});
document.addEventListener('input',e=>{if(e.target.matches('[data-attendance-note]')){const d=getDailyDraft(),id=e.target.dataset.attendanceNote;d[id]={...(d[id]||{}),note:e.target.value};let state=$('.attendanceSaveState');if(state){state.textContent='Not Saved Yet ⏳';state.classList.remove('saved');state.classList.add('unsaved')}}if(e.target.id==='attendanceDailySearch'||e.target.id==='attendanceMonthlySearch'){attendanceSearchText=e.target.value;const start=e.target.selectionStart;render();const input=$('#'+e.target.id);input?.focus();input?.setSelectionRange(start,start)}});
